import { createGame,captureState } from '../../src/simulation';
import { MVP_DEFAULT } from '../../src/content/scenarios/mvp-default';
import { command,place,until,WALKER_SEED } from './one-worker';
import { elevator } from './transport';
/** Build the SC-012 reference through public commands using explicit finite capacity/funding overrides. */
export function referenceTower(){const scenario={...MVP_DEFAULT,scenarioId:'storage-reference-2000',startingFundsMinor:5000000,content:{...MVP_DEFAULT.content,officeMarketWorkers:1920,restaurantDailyCustomers:80,definitions:MVP_DEFAULT.content.definitions.map(d=>d.typeId==='office.small'?{...d,capacity:80}:d)}};const s=createGame(scenario,WALKER_SEED);for(let floor=1;floor<=12;floor++){const result=command(s,{kind:'constructFloorRange',payload:{floor,startX:0,endXExclusive:96}});if(!result.ok)throw Error(result.code);place(s,24,floor);place(s,48,floor);}for(let lowerFloor=0;lowerFloor<12;lowerFloor++){const result=command(s,{kind:'buildStair',payload:{definitionId:'stairs.basic',lowerFloor,x:80+lowerFloor%2*2}});if(!result.ok)throw Error(result.code);}for(const x of [10,14,18])elevator(s,12,x);for(const x of [24,48]){const result=command(s,{kind:'placeFacility',payload:{definitionId:'restaurant.small',floor:0,x}});if(!result.ok)throw Error(result.code);}until(s,29160);const active=Object.values(s.occupants).filter(p=>!['outside','insideFacility'].includes(p.state)).length;if(Object.keys(s.occupants).length!==2000||active<500)throw Error(`Invalid reference population: ${active} active`);return captureState(s);}
